2. Concrete Command ClassesConcrete command classes implement the Command interface. Each class encapsulates a specific operation related to devices. Each concrete command class provides a specific implementation of the execute() method, defining how a particular device operation (turning on, turning off, adjusting volume, changing channel) is executed.
            C++

    #include <iostream>
using namespace std;

// Command Interface
class Command {
public:
    virtual void execute() = 0;
    virtual ~Command() {}
};

// Concrete Command for turning a device ON
class TurnOnCommand : public Command {
private:
    Device* device;
public:
    TurnOnCommand(Device* device) : device(device) {}
    void execute() override {
        device->turnOn();
    }
};

// Concrete Command for turning a device OFF
class TurnOffCommand : public Command {
private:
    Device* device;
public:
    TurnOffCommand(Device* device) : device(device) {}
    void execute() override {
        device->turnOff();
    }
};

// Concrete Command for adjusting Stereo volume
class AdjustVolumeCommand : public Command {
private:
    Stereo* stereo;
public:
    AdjustVolumeCommand(Stereo* stereo) : stereo(stereo) {}
    void execute() override {
        stereo->adjustVolume();
    }
};

// Concrete Command for changing TV channel
class ChangeChannelCommand : public Command {
private:
    TV* tv;
public:
    ChangeChannelCommand(TV* tv) : tv(tv) {}
    void execute() override {
        tv->changeChannel();
    }
};


