3. Receiver Classes (Devices)The Device interface declares methods related to device functionality, such as turnOn() and turnOff().This interface sets a contract for device classes, defining common operations that concrete devices should support.
            C++

    #include <iostream>

// Receiver Interface
class Device {
public:
    virtual void turnOn() = 0;
    virtual void turnOff() = 0;
};

// Concrete Receiver: TV
class TV : public Device {
public:
    void turnOn() override {
        std::cout << "TV is now on" << std::endl;
    }

    void turnOff() override {
        std::cout << "TV is now off" << std::endl;
    }

    void changeChannel() {
        std::cout << "Channel changed" << std::endl;
    }
};

// Concrete Receiver: Stereo
class Stereo : public Device {
public:
    void turnOn() override {
        std::cout << "Stereo is now on" << std::endl;
    }

    void turnOff() override {
        std::cout << "Stereo is now off" << std::endl;
    }

    void adjustVolume() {
        std::cout << "Volume adjusted" << std::endl;
    }
};


